import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione alla probabilità soggettiva","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfa.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lcfa.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lcfa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione-alla-probabilita-soggettiva" tabindex="-1">Introduzione alla probabilità soggettiva <a class="header-anchor" href="#introduzione-alla-probabilita-soggettiva" aria-label="Permalink to “Introduzione alla probabilità soggettiva”">​</a></h1><blockquote><p>Alla probabilità soggettiva è legato uno dei più bei ricordi della mia carriera di insegnante.</p></blockquote><p>Ci sono eventi per cui non è possibile dare una definizione precisa di probabilità: ad esempio qual è la probabilità che in una partita, ad esempio Inter-Roma vinca l&#39;Inter?</p><ul><li>Non possiamo usare la probabilità classica perché non possiamo definire il numero dei casi favorevoli ed il numero dei casi possibili</li><li>Non possiamo usare la probabilità frequentista perché in primo luogo sono pochi gli eventi accaduti su cui basarsi (le partite già effettuate fra Inter e Roma), inoltre una squadra non è fissa, ma varia a seconda della sua composizione e dello stato dei suoi componenti: se un attaccante si fa male sarà sostituito da un altro con diverse capacità agonistiche e le probabilità di vincita della squadra varieranno</li></ul><p>È però possibile prefigurarsi personalmente una probabilità dicendosi: &quot;Se si giocassero in questo momento <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> partite, secondo me, quante ne vincerebbe l&#39;Inter, quante la Roma e quante sarebbero pareggiate?&quot;</p><p>Se conosco bene l&#39;argomento ed il mio giudizio è abbastanza oggettivo, cioè non falsato da passione sportiva, ottengo una probabilità abbastanza accettabile</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};